class TestReplay(unittest.TestCase):
    def _apply(self, event, down_nodes, down_links):
        action = event["action"]
        if action == "node-down":
            down_nodes.add(event["node"])
        elif action == "node-up":
            down_nodes.discard(event["node"])
        else:
            pair = frozenset((event["from"], event["to"]))
            if action == "link-down":
                down_links.add(pair)
            else:
                down_links.discard(pair)

