def distance_vector_holddown_convergence(
    round_zero,
    holddowns_zero,
    ordered_nodes,
    active_adjacency,
    down_nodes,
    infinity_metric,
):
    """Record rounds under hold-down until both vectors and timers are stable.

    Round 0 is recorded as given; each later round is one synchronous
    hold-down update.  Rounds are recorded while either the forwarding vectors
    or the (published) hold-down map change, so ``convergenceRound`` points at
    the last round in which anything is still timing down.
    """
    rounds = [
        {
            "round": 0,
            "routers": round_zero,
            "holdDowns": holddowns_public(holddowns_zero, ordered_nodes),
        }
    ]
    vectors = round_zero
    holddowns = holddowns_zero
    while True:
        updated, next_holddowns = distance_vector_holddown_round(
            vectors,
            ordered_nodes,
            active_adjacency,
            down_nodes,
            infinity_metric,
            holddowns,
        )
        if updated == vectors and next_holddowns == holddowns:
            break
        vectors = updated
        holddowns = next_holddowns
        rounds.append(
            {
                "round": len(rounds),
                "routers": vectors,
                "holdDowns": holddowns_public(holddowns, ordered_nodes),
            }
        )
    return rounds, vectors

# ---------------------------------------------------------------------------
# Route hold-down (optional replay-dv suppression)
# ---------------------------------------------------------------------------
#
# A hold-down suppresses relearning a destination through a different
# neighbor for a finite number of full update rounds after the router's own
# finite route to that destination was invalidated.  Suppression state is a
# mapping ``{router: {destination: remaining_rounds}}`` carried beside (never
# inside) the advertised vectors, so a held route still advertises exactly
# ``null``/``null`` to neighbors and the event format is untouched.
#
# Timing convention: a freshly invalidated route is timed at ``hold_down`` at
# round 0 (the post-event round).  Each later synchronous transition first
# expires one round from timers carried into it; a route whose timer reaches
# zero at that transition rejoins normal selection in the same round.  Hence a
# route invalidated at round 0 is suppressed through round ``hold_down`` and
# relearnable from round ``hold_down + 1`` on -- "the round after the
# remainder reaches zero".  A repeat unreachable advertisement while the
# timer is alive never refreshes it; only an invalidation seen while no timer
# is alive arms one.


def _empty_holddowns(ordered_nodes):
    """A fresh ``{router: {destination: remaining}}`` map, one row per router."""
