        router: {
            destination: holddowns[router][destination]
            for destination in sorted(holddowns[router])
        }
        for router in ordered_nodes
    }


def distance_vector_holddown_round_zero(
    previous, ordered_nodes, active_adjacency, down_nodes, hold_down
):
    """Round 0 after an event with route hold-down enabled.

    Mirrors :func:`distance_vector_failure_round_zero` for reachability, but
    also arms the hold-down timer whenever an online router's previously
    finite route is invalidated because its selected next hop is no longer an
    available direct neighbor or that next hop now advertises the destination
    as unreachable, while the destination is not itself a current direct
    neighbor.  Returns ``(vectors, holddowns)``.
    """
    vectors = {}
    holddowns = _empty_holddowns(ordered_nodes)
    for router in ordered_nodes:
        if router in down_nodes:
            vectors[router] = _unreachable_row(ordered_nodes)
            continue
        table = {}
        timed = holddowns[router]
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
            elif destination in active_adjacency[router]:
                # A directly reachable destination is adopted at once and is
                # never held down.
                table[destination] = {
                    "nextHop": destination,
                    "metric": active_adjacency[router][destination],
                }
            else:
                entry = previous[router][destination]
                hop = entry["nextHop"]
                if hop is not None and hop not in active_adjacency[router]:
                    # The selected next hop of a previously finite route is no
                    # longer available (it failed or its link went down): the
                    # route is null at round 0 and its timer starts.
                    table[destination] = {"nextHop": None, "metric": None}
                    if hold_down > 0:
                        timed[destination] = hold_down
                elif hop is None or hop not in active_adjacency[router]:
                    table[destination] = {"nextHop": None, "metric": None}
                else:
                    table[destination] = dict(entry)
        vectors[router] = table
    return vectors, holddowns


def _hop_route_usable(router, destination, hop, previous, adjacency, infinity_metric):
    """Whether ``router``'s selected ``hop`` still offers a usable finite route.

    A next hop is unusable when it is no longer a current direct neighbor,
    advertises the destination as unreachable, or its advertisement reaches
    the infinity threshold -- the same three conditions that make an
    advertisement unselectable in an ordinary synchronous round.
    """
    if hop not in adjacency[router]:
        return False
    advertised = previous[hop][destination]["metric"]
    if advertised is None:
        return False
    return adjacency[router][hop] + advertised < infinity_metric


def distance_vector_holddown_round(
    previous, ordered_nodes, adjacency, down_nodes, infinity_metric, holddowns
):
    """One synchronous round with hold-down suppression.

    Returns ``(vectors, holddowns)``.  Each online router, for a destination
    that is not itself a current direct neighbor:

    * starts the timer and reports unreachable when its previously selected
      (finite) next hop has just become unusable -- unless a timer for that
      destination is already counting down, in which case the window is not
      extended;
    * while the timer is positive, reports unreachable and refuses every
      finite alternative advertisement (the timer counts down by one);
    * once the timer has reached zero (or was never armed) rejoins ordinary
      synchronous selection, preserving the infinity threshold and
      smaller-next-hop tie rule.

